    {
      "cell_type": "markdown",
      "metadata": {
        "id": "cjqY0QHPjrgG"
      },
      "source": [
        "## 1. Descriptive Statistical Analysis — `body_mass_g`"
      ]
    },
    {
      "cell_type": "code",
      "metadata": {
        "colab": {
          "base_uri": "https://localhost:8080/"
        },
        "id": "DuSo-_zBjrgG",
        "outputId": "119d2f6c-c59b-4ef3-d41d-c73b0c4ad0df"
      },
      "source": [
        "# ---- Skewness / kurtosis with base-R fallback ----------------------------\n",
        "# e1071 type=2 is the bias-corrected sample estimator; replicated manually below.\n",
        "skew_fn <- function(x) {\n",
        "  x <- x[!is.na(x)]\n",
        "  n <- length(x)\n",
        "  if (HAS_E) return(e1071::skewness(x, type = 2))\n",
        "  m <- mean(x); s <- sd(x)\n",
        "  g1 <- sum((x - m)^3) / (n * s^3)\n",
        "  sqrt(n * (n - 1)) / (n - 2) * g1\n",
        "}\n",
        "\n",
        "kurt_fn <- function(x) {\n",
        "  x <- x[!is.na(x)]\n",
        "  n <- length(x)\n",
        "  if (HAS_E) return(e1071::kurtosis(x, type = 2))\n",
        "  m <- mean(x); s <- sd(x)\n",
        "  g2 <- sum((x - m)^4) / (n * s^4) - 3\n",
        "  ((n + 1) * g2 + 6) * (n - 1) / ((n - 2) * (n - 3))\n",
        "}\n",
        "\n",
        "# ---- Reusable descriptive-statistics helper ------------------------------\n",
        "describe_var <- function(x) {\n",
        "  x <- x[!is.na(x)]\n",
        "  q <- as.numeric(quantile(x, probs = c(0.25, 0.75)))\n",
        "  data.frame(n        = length(x),\n",
        "             mean     = mean(x),\n",
        "             median   = median(x),\n",
        "             min      = min(x),\n",
        "             max      = max(x),\n",
        "             variance = var(x),\n",
        "             sd       = sd(x),\n",
        "             Q1       = q[1],\n",
        "             Q3       = q[2],\n",
        "             IQR      = IQR(x),\n",
        "             skewness = skew_fn(x),\n",
        "             kurtosis = kurt_fn(x))\n",
        "}\n",
        "\n",
        "# Grouped descriptives via base-R split/lapply (works without dplyr)\n",
        "describe_by <- function(values, group) {\n",
        "  parts <- split(values, group)\n",
        "  out   <- do.call(rbind, lapply(parts, describe_var))\n",
        "  data.frame(group = names(parts), round(out, 3), row.names = NULL)\n",
        "}\n",
        "\n",
        "cat(\"=== Overall descriptive statistics: body_mass_g ===\\n\")\n",
        "print(round(describe_var(peng$body_mass_g), 3))"
      ],
      "execution_count": 4,
      "outputs": [
        {
          "output_type": "stream",
          "name": "stdout",
          "text": [
            "=== Overall descriptive statistics: body_mass_g ===\n",
            "    n     mean median  min  max variance      sd   Q1   Q3  IQR skewness\n",
            "1 333 4207.057   4050 2700 6300 648372.5 805.216 3550 4775 1225    0.472\n",
            "  kurtosis\n",
            "1   -0.733\n"
          ]
        }
      ]
    },
