    {
      "cell_type": "code",
      "metadata": {
        "colab": {
          "base_uri": "https://localhost:8080/",
          "height": 917
        },
        "id": "3eJx5UMdjrgH",
        "outputId": "1c6ce0ff-16b4-4478-8d53-74cc3fc8bc33"
      },
      "source": [
        "# ---- Boxplots: species and sex ------------------------------------------\n",
        "par(mfrow = c(1, 2))\n",
        "\n",
        "boxplot(body_mass_g ~ species, data = peng,\n",
        "        col  = c(\"#E69F00\", \"#56B4E9\", \"#009E73\"),\n",
        "        main = \"Body Mass by Species\",\n",
        "        xlab = \"Species\", ylab = \"Body mass (g)\")\n",
        "\n",
        "boxplot(body_mass_g ~ sex, data = peng,\n",
        "        col  = c(\"#CC79A7\", \"#0072B2\"),\n",
        "        main = \"Body Mass by Sex\",\n",
        "        xlab = \"Sex\", ylab = \"Body mass (g)\")\n",
        "\n",
        "par(mfrow = c(1, 1))\n",
        "\n",
        "if (HAS_GG) {\n",
        "  print(ggplot(peng, aes(x = species, y = body_mass_g, fill = species)) +\n",
        "          geom_boxplot(alpha = 0.8, outlier.shape = 21) +\n",
        "          labs(title = \"Body Mass by Penguin Species\",\n",
        "               x = \"Species\", y = \"Body mass (g)\", fill = \"Species\") +\n",
        "          theme_minimal(base_size = 13))\n",
        "\n",
        "  print(ggplot(peng, aes(x = sex, y = body_mass_g, fill = sex)) +\n",
