    {
      "cell_type": "code",
      "metadata": {
        "colab": {
          "base_uri": "https://localhost:8080/",
          "height": 617
        },
        "id": "B06PmF7gjrgI",
        "outputId": "06389634-dcf5-4b70-9243-c38a653672ee"
      },
      "source": [
        "# ---- Density plots -------------------------------------------------------\n",
        "sp   <- levels(peng$species)\n",
        "cols <- c(\"#E69F00\", \"#56B4E9\", \"#009E73\")\n",
        "dens <- lapply(sp, function(s) density(peng$body_mass_g[peng$species == s]))\n",
        "\n",
        "plot(density(peng$body_mass_g),\n",
        "     lwd  = 2, col = \"black\",\n",
        "     ylim = c(0, max(sapply(dens, function(d) max(d$y)))),\n",
        "     main = \"Density of Body Mass: Overall and by Species\",\n",
        "     xlab = \"Body mass (g)\", ylab = \"Density\")\n",
        "\n",
        "for (i in seq_along(dens)) lines(dens[[i]], col = cols[i], lwd = 2)\n",
        "\n",
        "legend(\"topright\", legend = c(\"Overall\", sp),\n",
        "       col = c(\"black\", cols), lwd = 2, bty = \"n\")\n",
        "\n",
        "if (HAS_GG) {\n",
