    {
      "cell_type": "code",
      "metadata": {
        "colab": {
          "base_uri": "https://localhost:8080/"
        },
        "id": "EZL5GP9BjrgJ",
        "outputId": "b22bccc9-5536-416d-8f54-7b9fa97d5fe9"
      },
      "source": [
        "# ---- Homogeneity of variance -------------------------------------------\n",
        "# Levene's test via car if available; Bartlett + F-test always available.\n",
        "if (HAS_CAR) {\n",
        "  cat(\"--- Levene's test (car, median-centred) ---\\n\")\n",
        "  print(car::leveneTest(body_mass_g ~ sex, data = peng))\n",
        "} else {\n",
        "  cat(\"car unavailable - using Levene's test computed manually\\n\")\n",
        "  # Levene = ANOVA on absolute deviations from the group median\n",
        "  med <- tapply(peng$body_mass_g, peng$sex, median)\n",
        "  dev <- abs(peng$body_mass_g - med[as.character(peng$sex)])\n",
        "  print(summary(aov(dev ~ peng$sex)))\n",
        "}\n",
        "\n",
        "cat(\"\\n--- Bartlett's test ---\\n\")\n",
        "print(bartlett.test(body_mass_g ~ sex, data = peng))\n",
        "\n",
        "cat(\"\\n--- F-test for equal variances ---\\n\")\n",
        "print(var.test(body_mass_g ~ sex, data = peng))"
      ],
      "execution_count": 11,
