        },
        "id": "ah11mG-djrgJ",
        "outputId": "180d5bff-d117-4215-83c2-3a18947bf334"
      },
      "source": [
        "# ---- Welch two-sample t-test (unequal variances) -----------------------\n",
        "t_welch <- t.test(body_mass_g ~ sex, data = peng, var.equal = FALSE)\n",
        "print(t_welch)\n",
        "\n",
        "cat(\"\\n95% CI for (female - male) mean difference: [\",\n",
        "    round(t_welch$conf.int[1], 2), \",\",\n",
        "    round(t_welch$conf.int[2], 2), \"] g\\n\")\n",
        "\n",
        "cat(\"\\n--- Student's pooled-variance t-test (for comparison) ---\\n\")\n",
        "print(t.test(body_mass_g ~ sex, data = peng, var.equal = TRUE))"
      ],
      "execution_count": 12,
      "outputs": [
        {
          "output_type": "stream",
