      },
      "source": [
        "# ---- QQ-plots by species -----------------------------------------------\n",
        "par(mfrow = c(1, 3))\n",
        "\n",
        "for (s in levels(peng$species)) {\n",
        "  x <- peng$body_mass_g[peng$species == s]\n",
        "  qqnorm(x, main = paste(\"QQ:\", s))\n",
        "  qqline(x, col = \"red\", lwd = 2)\n",
        "}\n",
        "\n",
        "par(mfrow = c(1, 1))\n",
        "\n",
        "if (HAS_GG) {\n",
        "  print(ggplot(peng, aes(sample = body_mass_g)) +\n",
        "          stat_qq() +\n",
        "          stat_qq_line(colour = \"red\") +\n",
        "          facet_wrap(~ species, scales = \"free\") +\n",
        "          labs(title = \"Normal QQ-Plots of Body Mass by Species\",\n",
        "               x = \"Theoretical quantiles\", y = \"Sample quantiles\") +\n",
        "          theme_minimal(base_size = 13))\n",
        "}"
      ],
