        "# ---- Post-hoc: Tukey's HSD --------------------------------------------\n",
        "tuk <- TukeyHSD(aov1)\n",
        "print(tuk)\n",
        "\n",
        "par(mar = c(5, 10, 4, 2))\n",
        "plot(tuk, las = 1)\n",
        "par(mar = c(5, 4, 4, 2))"
      ],
