      "source": [
        "# ---- Two-way ANOVA with interaction -----------------------------------\n",
        "aov2 <- aov(body_mass_g ~ species * sex, data = peng)\n",
        "\n",
        "cat(\"=== Two-way ANOVA: body_mass_g ~ species * sex ===\\n\")\n",
        "print(summary(aov2))\n",
        "\n",
        "if (HAS_CAR) {\n",
        "  cat(\"\\n=== Type II sums of squares (preferred for unbalanced designs) ===\\n\")\n",
        "  print(car::Anova(aov2, type = \"II\"))\n",
        "}"
      ],
      "execution_count": 25,
