      },
      "source": [
        "# ---- Grouped boxplot: species x sex -----------------------------------\n",
        "boxplot(body_mass_g ~ sex + species, data = peng,\n",
        "        col  = rep(c(\"#CC79A7\", \"#0072B2\"), 3),\n",
        "        las  = 2,\n",
        "        main = \"Body Mass by Species and Sex\",\n",
        "        xlab = \"\", ylab = \"Body mass (g)\")\n",
        "\n",
        "legend(\"topleft\", legend = levels(peng$sex),\n",
        "       fill = c(\"#CC79A7\", \"#0072B2\"), bty = \"n\")\n",
        "\n",
        "if (HAS_GG) {\n",
        "  print(ggplot(peng, aes(x = species, y = body_mass_g, fill = sex)) +\n",
        "          geom_boxplot(alpha = 0.85, outlier.shape = 21) +\n",
        "          labs(title = \"Body Mass Distribution by Species and Sex\",\n",
        "               x = \"Species\", y = \"Body mass (g)\", fill = \"Sex\") +\n",
        "          theme_minimal(base_size = 13))\n",
        "}"
      ],
      "execution_count": 27,
      "outputs": [
        {
          "output_type": "display_data",
          "data": {
            "text/plain": [
