      "source": [
        "# ---- Tukey on the two-way model ---------------------------------------\n",
        "cat(\"--- Tukey HSD: species ---\\n\")\n",
        "print(TukeyHSD(aov2, which = \"species\"))\n",
        "\n",
        "cat(\"\\n--- Tukey HSD: sex ---\\n\")\n",
        "print(TukeyHSD(aov2, which = \"sex\"))"
      ],
      "execution_count": 28,
      "outputs": [
        {
          "output_type": "stream",
          "name": "stdout",
          "text": [
            "--- Tukey HSD: species ---\n",
            "  Tukey multiple comparisons of means\n",
            "    95% family-wise confidence level\n",
            "\n",
            "Fit: aov(formula = body_mass_g ~ species * sex, data = peng)\n",
            "\n",
            "$species\n",
            "                       diff       lwr       upr     p adj\n",
            "Chinstrap-Adelie   26.92385  -80.0258  133.8735 0.8241288\n",
            "Gentoo-Adelie    1386.27259 1296.3070 1476.2382 0.0000000\n",
            "Gentoo-Chinstrap 1359.34874 1248.6108 1470.0866 0.0000000\n",
            "\n",
            "\n",
            "--- Tukey HSD: sex ---\n",
            "  Tukey multiple comparisons of means\n",
            "    95% family-wise confidence level\n",
            "\n",
            "Fit: aov(formula = body_mass_g ~ species * sex, data = peng)\n",
            "\n",
            "$sex\n",
            "                diff      lwr      upr p adj\n",
            "male-female 667.4577 600.7462 734.1692     0\n",
            "\n"
          ]
        }
      ]
