      },
      "source": [
        "# ---- Assumption checks -------------------------------------------------\n",
        "for (s in levels(peng$species)) {\n",
        "  x <- peng$flipper_length_mm[peng$species == s]\n",
        "  cat(\"\\n--- Shapiro-Wilk (flipper length):\", s, \"---\\n\")\n",
        "  print(shapiro.test(x))\n",
        "}\n",
        "\n",
        "cat(\"\\n--- Homogeneity of variance ---\\n\")\n",
        "if (HAS_CAR) {\n",
        "  print(car::leveneTest(flipper_length_mm ~ species, data = peng))\n",
        "} else {\n",
        "  med <- tapply(peng$flipper_length_mm, peng$species, median)\n",
        "  dev <- abs(peng$flipper_length_mm - med[as.character(peng$species)])\n",
        "  print(summary(aov(dev ~ peng$species)))\n",
        "}"
      ],
      "execution_count": 30,
      "outputs": [
        {
          "output_type": "stream",
          "name": "stdout",
          "text": [
            "\n",
