    {
      "cell_type": "code",
      "metadata": {
        "colab": {
          "base_uri": "https://localhost:8080/"
        },
        "id": "k_M9baabjrgM",
        "outputId": "fd696455-3a72-4bbb-f735-fd7564378ee1"
      },
      "source": [
        "# ---- ANOVA + Tukey + Kruskal-Wallis on flipper length -----------------\n",
        "aov_flip <- aov(flipper_length_mm ~ species, data = peng)\n",
        "\n",
        "cat(\"=== One-way ANOVA: flipper_length_mm ~ species ===\\n\")\n",
        "print(summary(aov_flip))\n",
        "\n",
        "tabf <- summary(aov_flip)[[1]]\n",
        "ssf  <- tabf[[\"Sum Sq\"]]\n",
        "\n",
        "cat(\"\\nF =\", round(tabf[[\"F value\"]][1], 2),\n",
        "    \" df = (\", tabf[[\"Df\"]][1], \",\", tabf[[\"Df\"]][2], \")\",\n",
        "    \" p =\", format.pval(tabf[[\"Pr(>F)\"]][1], digits = 4),\n",
        "    \" eta-squared =\", round(ssf[1] / sum(ssf), 4), \"\\n\")\n",
        "\n",
        "cat(\"\\n=== Tukey HSD ===\\n\")\n",
        "print(TukeyHSD(aov_flip))\n",
        "\n",
        "cat(\"\\n=== Kruskal-Wallis ===\\n\")\n",
        "print(kruskal.test(flipper_length_mm ~ species, data = peng))\n",
        "\n",
        "cat(\"\\n=== Pairwise Wilcoxon (Holm) ===\\n\")\n",
        "print(pairwise.wilcox.test(peng$flipper_length_mm, peng$species,\n",
        "                           p.adjust.method = \"holm\"))"
      ],
      "execution_count": 32,
      "outputs": [
        {
          "output_type": "stream",
