      "source": [
        "# ---- Species-wise flipper-length comparison plot ----------------------\n",
        "boxplot(flipper_length_mm ~ species, data = peng,\n",
        "        col  = c(\"#E69F00\", \"#56B4E9\", \"#009E73\"),\n",
        "        main = \"Flipper Length by Penguin Species\",\n",
        "        xlab = \"Species\", ylab = \"Flipper length (mm)\")\n",
        "\n",
        "stripchart(flipper_length_mm ~ species, data = peng,\n",
        "           method = \"jitter\", vertical = TRUE, add = TRUE,\n",
        "           pch = 1, cex = 0.5, col = rgb(0, 0, 0, 0.3))\n",
        "\n",
        "if (HAS_GG) {\n",
        "  print(ggplot(peng, aes(x = species, y = flipper_length_mm, fill = species)) +\n",
        "          geom_boxplot(alpha = 0.8, outlier.shape = 21, width = 0.6) +\n",
        "          geom_jitter(width = 0.12, alpha = 0.25, size = 1) +\n",
        "          labs(title    = \"Flipper Length by Penguin Species\",\n",
        "               subtitle = \"Boxplot with individual observations overlaid\",\n",
        "               x = \"Species\", y = \"Flipper length (mm)\", fill = \"Species\") +\n",
        "          theme_minimal(base_size = 13))\n",
        "}"
      ],
