      },
      "source": [
        "# ---- Group comparison plot: Tukey differences with 95% family-wise CIs -\n",
        "td <- as.data.frame(TukeyHSD(aov1)$species)\n",
        "td$comparison <- rownames(td)\n",
        "td <- td[order(td$diff), ]\n",
        "sig <- td[[\"p adj\"]] < 0.05\n",
        "\n",
        "par(mar = c(5, 11, 4, 2))\n",
        "\n",
        "plot(td$diff, seq_len(nrow(td)),\n",
        "     xlim = range(c(td$lwr, td$upr, 0)),\n",
        "     yaxt = \"n\", pch = 19, cex = 1.4,\n",
        "     col  = ifelse(sig, \"firebrick\", \"grey55\"),\n",
        "     xlab = \"Difference in mean body mass (g)\", ylab = \"\",\n",
        "     main = \"Tukey HSD: Pairwise Differences in Mean Body Mass\")\n",
        "\n",
        "arrows(td$lwr, seq_len(nrow(td)), td$upr, seq_len(nrow(td)),\n",
        "       angle = 90, code = 3, length = 0.05,\n",
        "       col = ifelse(sig, \"firebrick\", \"grey55\"), lwd = 2)\n",
        "\n",
        "abline(v = 0, lty = 2, col = \"grey30\")\n",
        "axis(2, at = seq_len(nrow(td)), labels = td$comparison, las = 1)\n",
        "\n",
        "legend(\"bottomright\",\n",
        "       legend = c(\"Significant (p < 0.05)\", \"Not significant\"),\n",
        "       col = c(\"firebrick\", \"grey55\"), pch = 19, bty = \"n\")\n",
        "\n",
        "par(mar = c(5, 4, 4, 2))"
      ],
      "execution_count": 35,
