      "source": [
        "# ---- Body mass vs flipper length, by species --------------------------\n",
        "cols3 <- c(\"#E69F00\", \"#56B4E9\", \"#009E73\")\n",
        "\n",
        "plot(peng$flipper_length_mm, peng$body_mass_g,\n",
        "     col  = cols3[as.integer(peng$species)],\n",
        "     pch  = ifelse(peng$sex == \"male\", 17, 16),\n",
        "     xlab = \"Flipper length (mm)\", ylab = \"Body mass (g)\",\n",
        "     main = \"Body Mass vs Flipper Length by Species and Sex\")\n",
        "\n",
        "for (i in seq_along(levels(peng$species))) {\n",
        "  s   <- levels(peng$species)[i]\n",
        "  sub <- peng[peng$species == s, ]\n",
        "  abline(lm(body_mass_g ~ flipper_length_mm, data = sub), col = cols3[i], lwd = 2)\n",
        "}\n",
        "\n",
        "legend(\"topleft\", legend = levels(peng$species), col = cols3, pch = 19, bty = \"n\")\n",
        "legend(\"bottomright\", legend = c(\"female\", \"male\"), pch = c(16, 17), bty = \"n\")\n",
        "\n",
        "if (HAS_GG) {\n",
        "  print(ggplot(peng, aes(x = flipper_length_mm, y = body_mass_g,\n",
        "                         colour = species, shape = sex)) +\n",
        "          geom_point(size = 2.2, alpha = 0.85) +\n",
        "          geom_smooth(aes(group = species), method = \"lm\", se = FALSE) +\n",
        "          labs(title    = \"Body Mass vs Flipper Length by Species and Sex\",\n",
        "               subtitle = \"Lines = per-species linear fits\",\n",
        "               x = \"Flipper length (mm)\", y = \"Body mass (g)\",\n",
        "               colour = \"Species\", shape = \"Sex\") +\n",
        "          theme_minimal(base_size = 13))\n",
        "}"
      ],
