        "id": "nIo9DcYKjrgN",
        "outputId": "811c3055-7b5e-49b4-e108-9127bbf0533c"
      },
      "source": [
        "# ---- Why flipper length separates the species better ------------------\n",
        "par(mfrow = c(1, 2))\n",
        "\n",
        "for (v in c(\"body_mass_g\", \"flipper_length_mm\")) {\n",
        "  dl <- lapply(levels(peng$species), function(s) density(peng[[v]][peng$species == s]))\n",
        "  plot(dl[[1]],\n",
        "       xlim = range(peng[[v]]),\n",
        "       ylim = c(0, max(sapply(dl, function(d) max(d$y)))),\n",
        "       col  = cols3[1], lwd = 2,\n",
        "       main = if (v == \"body_mass_g\") \"Body mass (g)\" else \"Flipper length (mm)\",\n",
        "       xlab = v, ylab = \"Density\")\n",
        "  for (i in 2:3) lines(dl[[i]], col = cols3[i], lwd = 2)\n",
        "  legend(\"topright\", legend = levels(peng$species), col = cols3, lwd = 2, bty = \"n\")\n",
        "}\n",
        "\n",
        "par(mfrow = c(1, 1))"
      ],
      "execution_count": 37,
      "outputs": [
        {
          "output_type": "display_data",
          "data": {
            "text/plain": [
