      "source": [
        "# ---- Final results summary --------------------------------------------\n",
        "results <- data.frame(\n",
        "  Analysis = c(\"Welch t-test: mass ~ sex\",\n",
        "               \"One-way ANOVA: mass ~ species\",\n",
        "               \"Kruskal-Wallis: mass ~ species\",\n",
        "               \"Two-way ANOVA: species\",\n",
        "               \"Two-way ANOVA: sex\",\n",
        "               \"Two-way ANOVA: species x sex\",\n",
        "               \"One-way ANOVA: flipper ~ species\",\n",
        "               \"Kruskal-Wallis: flipper ~ species\"),\n",
        "  Conclusion = c(\"Reject H0 - males heavier; large effect (d ~ -0.94)\",\n",
        "                 \"Reject H0 - Gentoo heavier; Adelie vs Chinstrap NOT significant\",\n",
        "                 \"Reject H0 - same conclusion as ANOVA\",\n",
        "                 \"Significant\",\n",
        "                 \"Significant\",\n",
        "                 \"Significant - dimorphism largest in Gentoo\",\n",
        "                 \"Reject H0 - ALL three pairs differ significantly\",\n",
        "                 \"Reject H0 - agrees with ANOVA\"),\n",
        "  stringsAsFactors = FALSE\n",
        ")\n",
        "\n",
        "print(results, row.names = FALSE, right = FALSE)"
      ],
      "execution_count": 38,
      "outputs": [
        {
          "output_type": "stream",
          "name": "stdout",
